CREATE TABLE IF NOT EXISTS `annonces_refcontact_{contactRef}` ( `A_RefAnn` bigint(10) unsigned NOT NULL auto_increment, `A_RefAnnGlob` int(10) unsigned NOT NULL DEFAULT '0', `A_Actif` tinyint(4) NOT NULL default '1', `A_Source` varchar(50) NOT NULL, `A_Annonceur` varchar(50) NOT NULL, `A_TelAnnonceur` varchar(14) NOT NULL, `A_Date_Aspi` date NOT NULL, `A_Date_Aff` date NOT NULL, `A_Pos` int(11) NOT NULL default '9999999', `A_Image` varchar(255) default NULL, `A_Prix` varchar(12) default NULL, `A_Ville` varchar(50) default NULL, `A_Type` varchar(50) default NULL, `A_NbPieces` tinyint(3) unsigned default '0', `A_Surf` int(11) unsigned NOT NULL default '0', `A_Etage` varchar(2) default NULL, `A_NbChambres` varchar(2) default NULL, `A_Desc` varchar(3000) default NULL, `A_Lien` varchar(255) NOT NULL, `A_Com` varchar(200) NOT NULL, `A_Rate` int(11) unsigned NOT NULL default '0', `A_Dedouble` int(11) unsigned NOT NULL default '0', `A_EstExclusif` tinyint(1) NOT NULL default '0', `A_EstDernierEtage` tinyint(1) NOT NULL default '0', UNIQUE KEY `A_Lien` (`A_Lien`), PRIMARY KEY `A_RefAnn` (`A_RefAnn`), KEY `A_RefAnnGlob` (`A_RefAnnGlob`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 AUTO_INCREMENT=1;
CREATE TRIGGER annonces_refcontact_{contactRef}_oninsert AFTER INSERT ON annonces_refcontact_{contactRef} FOR EACH ROW BEGIN
-- bon contact ? SET @refconseiller := (SELECT CP_RefConseiller FROM conseillers_personnels cp INNER JOIN contacts_recherche c ON c.C_NomFamilleConseiller=cp.CP_Login WHERE cp.CP_Actif=1 AND cp.CP_Login IS NOT NULL AND cp.CP_Login <> '' AND c.C_RefContact={contactRef} AND c.C_Statut='CLIENT ACTIF' AND c.C_TypeRecherche='0' AND c.C_AlerteMail=1);
IF @refconseiller is not NULL AND NEW.A_RefAnnGlob IS NOT NULL && NEW.A_RefAnnGlob <> 0 AND NEW.A_Actif = 1 THEN
SET @gr := (SELECT ag.AG_Ref_AGC FROM annonces_globales ag WHERE ag.AG_Ref=NEW.A_RefAnnGlob);
-- nouveau A_RefAnnGlob ? SET @nb := (SELECT COUNT(*) FROM annonces_globales ag WHERE ag.AG_Ref_AGC=@gr AND ag.AG_Ref <> NEW.A_RefAnnGlob); -- SET @nb := (SELECT COUNT(*) FROM annonces_globales ag WHERE ag.AG_Ref_AGC=@gr); IF @nb = 0 THEN INSERT INTO `notifications` (`N_Type`, `N_RefConseiller`, `N_RefContact`, `N_RefAnn`, `N_CreatedOn`, `N_State`, `N_NewPrix`) VALUES ('NOUVEAU BIEN', @refconseiller, '{contactRef}', NEW.A_RefAnn, NOW(), '0', NEW.A_Prix); END IF; END IF; END;
CREATE TRIGGER annonces_refcontact_{contactRef}_onupdate AFTER UPDATE ON annonces_refcontact_{contactRef} FOR EACH ROW BEGIN -- bon contact ? SET @refconseiller := (SELECT CP_RefConseiller FROM conseillers_personnels cp INNER JOIN contacts_recherche c ON c.C_NomFamilleConseiller=cp.CP_Login WHERE cp.CP_Actif=1 AND cp.CP_Login IS NOT NULL AND cp.CP_Login <> '' AND c.C_RefContact={contactRef} AND c.C_Statut='CLIENT ACTIF' AND c.C_TypeRecherche='0' AND c.C_AlerteMail=1);
IF @refconseiller is not NULL AND NEW.A_RefAnnGlob IS NOT NULL && NEW.A_RefAnnGlob <> 0 AND NEW.A_Actif = 1 THEN
IF OLD.A_RefAnnGlob IS NULL THEN -- on considère ça comme un INSERT ! SET @gr := (SELECT ag.AG_Ref_AGC FROM annonces_globales ag WHERE ag.AG_Ref=NEW.A_RefAnnGlob);
-- nouveau A_RefAnnGlob ? SET @nb := (SELECT COUNT(*) FROM annonces_globales ag WHERE ag.AG_Ref_AGC=@gr AND ag.AG_Ref <> NEW.A_RefAnnGlob); -- SET @nb := (SELECT COUNT(*) FROM annonces_globales ag WHERE ag.AG_Ref_AGC=@gr); IF @nb = 0 THEN INSERT INTO `notifications` (`N_Type`, `N_RefConseiller`, `N_RefContact`, `N_RefAnn`, `N_CreatedOn`, `N_State`, `N_NewPrix`) VALUES ('NOUVEAU BIEN', @refconseiller, '{contactRef}', NEW.A_RefAnn, NOW(), '0', NEW.A_Prix); END IF; ELSEIF OLD.A_Prix <> NEW.A_Prix THEN INSERT INTO `notifications` (`N_Type`, `N_RefConseiller`, `N_RefContact`, `N_RefAnn`, `N_CreatedOn`, `N_State`, `N_OldPrix`, `N_NewPrix`) VALUES ('MODIF PRIX', @refconseiller, '{contactRef}', NEW.A_RefAnn, NOW(), '0', OLD.A_Prix, NEW.A_Prix); END IF; END IF;
-- on met à jour property_contact SET @propertyId := (SELECT AG_IdPropertyYanport FROM annonces_globales ag WHERE ag.AG_Ref=NEW.A_RefAnnGlob); IF @propertyId is not NULL THEN -- rien UPDATE property_contact SET PC_Rate=NEW.A_Rate, PC_Com=NEW.A_Com, PC_Actif=NEW.A_Actif, PC_Vu=CASE WHEN NEW.A_Date_Aff IS NULL OR NEW.A_Date_Aff='0000-00-00' THEN 0 ELSE 1 END WHERE PC_PropertyId=@propertyId AND PC_RefContact={contactRef}; END IF; END ;

